UpdateSourceArgs:
-c "mkdir -p config; cat > apply-config.sh << 'SCRIPT'
#!/bin/bash
# Apply key=value into [section] of a TOML-like file without destroying the rest
CONF=\"${1:-config/default.conf}\"
shift
[ -f \"$CONF\" ] || { echo \"Config not found: $CONF\"; exit 1; }
while [ \$# -ge 3 ]; do
  KEY=\"$1\"; VAL=\"$2\"; SEC=\"$3\"; shift 3
  case \"$VAL\" in
    true|True|TRUE) VAL=true ;;
    false|False|FALSE) VAL=false ;;
  esac
  case \"$VAL\" in
    true|false|[0-9]*) Q=\"$VAL\" ;;
    *) Q=\"\\\"$VAL\\\"\" ;;
  esac
  awk -v sec=\"$SEC\" -v key=\"$KEY\" -v q=\"$Q\" '
    BEGIN { insec=0 }
    /^\[/ { insec = ($0 == \"[\" sec \"]\") }
    insec && $0 ~ (\"^[[:space:]]*\" key \"[[:space:]]*=\") {
      print key \" = \" q
      next
    }
    { print }
  ' \"$CONF\" > \"$CONF.tmp\" && mv \"$CONF.tmp\" \"$CONF\"
done
SCRIPT
chmod +x apply-config.sh
echo 'Installed apply-config.sh'
"
